#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
use caliper_docgen_core::pipeline::{extract, HtmlAttributeMode, PipelineOptions};
use camino::Utf8PathBuf;
use tempfile::TempDir;

fn run(label: &str, files: &[(&str, &str)]) {
    let tmp = TempDir::new_in(env!("CARGO_MANIFEST_DIR")).unwrap();
    let root = Utf8PathBuf::from_path_buf(tmp.path().to_owned()).unwrap();
    for (name, src) in files {
        std::fs::write(root.join(name), src).unwrap();
    }
    let options = PipelineOptions {
        src_dirs: vec![root.clone()],
        cache_dir: Some(root.join(".cache")),
        html_attributes: HtmlAttributeMode::Full,
        ..Default::default()
    };
    let output = extract(&options);
    println!("=== {label}");
    for (k, e) in &output.components {
        let props: Vec<_> = e.props.keys().cloned().collect();
        println!("  {k}: props={props:?}");
    }
    for d in &output.diagnostics {
        println!("  diag {:?} {}", d.code, d.message);
    }
}

