25	    /// later, unrelated element's tag scan — e.g. a `@deprecated` tag on one prop would
26	    /// bleed onto sibling props with no JSDoc of their own. Sharing the same consumed-set
27	    /// lookup for both makes that impossible.
28	    ///
29	    /// `self.comments` is sorted by span (source order), so the candidate window is
30	    /// located via binary search rather than a linear scan — callers run one of these
31	    /// per prop/interface/component, and a full rescan-per-call is quadratic in file size.
32	    pub(super) fn find_jsdoc_with_tags(&mut self, span_start: u32) -> (String, BTreeMap<String, String>) {
33	        const PROXIMITY_THRESHOLD: u32 = 120; // bytes — enough for blank lines + decorator
34	
35	        let upper = self.comments.partition_point(|c| c.span_end <= span_start);
36	        let mut found: Option<usize> = None;
37	        for i in (0..upper).rev() {
38	            let c = &self.comments[i];
39	            if span_start - c.span_end > PROXIMITY_THRESHOLD {
40	                // Comments are sorted ascending by span, so every earlier comment
41	                // is farther still — nothing left in range.
42	                break;
43	            }
44	            if c.is_block && !self.consumed_jsdoc.contains(&c.span_end) {
45	                // A comment documents the declaration right after it, so one that something else stands between belongs
46	                // to that something: the props of `function Badge(props: { a: string })` follow the component's
47	                // comment, but `Badge(props:` is in the way.
48	                if documents_what_follows(&self.source[c.span_end as usize..span_start as usize]) {
49	                    found = Some(i);
50	                }
51	                break;
52	            }
53	        }
54	
55	        let Some(i) = found else { return (String::new(), BTreeMap::new()) };
56	        let c = &self.comments[i];
57	        let span_end = c.span_end;
58	        let raw = &self.source[c.span_start as usize..c.span_end as usize];
59	        let text = parse_jsdoc_text(raw);
60	        let tags = extract_jsdoc_tags(raw);
